from fastapi import APIRouter, FastAPI, Response
from fastapi.testclient import TestClient


def test_default_response_headers_are_injected():
    """All keys from the per-route `default_response_headers` are added to
    every response returned from the route when the response does not
    already have a value for that header."""
    app = FastAPI()

    @app.get(
        "/cached-item",
        default_response_headers={
            "Cache-Control": "max-age=300",
            "X-Source": "db",
        },
    )
    def cached_item():
        return {"item_id": "abc"}

    client = TestClient(app)
    response = client.get("/cached-item")

    assert response.status_code == 200
    assert response.headers["cache-control"] == "max-age=300"
    assert response.headers["x-source"] == "db"


def test_handler_set_header_is_not_overridden():
    """When the route handler sets a header explicitly (via the injected
    `Response` object), the handler's value wins and the default value
    declared on the route is not applied."""
    app = FastAPI()

    @app.get(
        "/override",
        default_response_headers={
            "Cache-Control": "max-age=300",
            "X-Source": "db",
        },
    )
    def override(response: Response):
        # The handler explicitly sets Cache-Control; the default value
        # for that header must be ignored.
        response.headers["Cache-Control"] = "no-store"
        return {"item_id": "abc"}

    client = TestClient(app)
    response = client.get("/override")

    assert response.status_code == 200
    assert response.headers["cache-control"] == "no-store"
    # Headers not set by the handler should still be injected.
    assert response.headers["x-source"] == "db"


def test_default_response_headers_propagate_via_router():
    """`default_response_headers` propagates through `APIRouter` helpers
    and survives `include_router`."""
    app = FastAPI()
    router = APIRouter()

    @router.get(
        "/router-cached",
        default_response_headers={"Cache-Control": "max-age=600"},
    )
    def router_cached():
        return {"ok": True}

    app.include_router(router)

    client = TestClient(app)
    response = client.get("/router-cached")

    assert response.status_code == 200
    assert response.headers["cache-control"] == "max-age=600"


def test_missing_default_response_headers_is_a_noop():
    """When `default_response_headers` is not provided (or is None), the
    behavior is unchanged from before this feature was added."""
    app = FastAPI()

    @app.get("/no-defaults")
    def no_defaults():
        return {"ok": True}

    client = TestClient(app)
    response = client.get("/no-defaults")

    assert response.status_code == 200
    # No Cache-Control or X-Source should have been introduced by FastAPI.
    assert "cache-control" not in {k.lower() for k in response.headers.keys()}
    assert "x-source" not in {k.lower() for k in response.headers.keys()}

